  const moveStop = async (index, direction) => {
    const newStops = [...stops]; 
    const target = index + direction; 
    if (target < 0 || target >= newStops.length) return;
    
    pushHistory();
    const updates = {};
    
    updates[`projects/${currentProject}/stops/${newStops[index].id}/startDate`] = newStops[target].startDate;
    updates[`projects/${currentProject}/stops/${newStops[index].id}/endDate`] = newStops[target].endDate;
    updates[`projects/${currentProject}/stops/${newStops[index].id}/stopNum`] = newStops[target].stopNum;
    updates[`projects/${currentProject}/stops/${newStops[target].id}/startDate`] = newStops[index].startDate;
    updates[`projects/${currentProject}/stops/${newStops[target].id}/endDate`] = newStops[index].endDate;
    updates[`projects/${currentProject}/stops/${newStops[target].id}/stopNum`] = newStops[index].stopNum;
    
    await dataService.batchUpdate(updates);
  };

  // 智能默认值：基于最新站点推断新阶段、周次、颜色和下一站号
  const getSmartNewStopDefaults = () => {
    if (stops.length === 0) return { ...initialStopState, stopNum: '1' };
    const sorted = [...stops].sort((a, b) => (parseFloat(a.stopNum) || 0) - (parseFloat(b.stopNum) || 0));
    const last = sorted[sorted.length - 1];
    const nextNum = String((parseFloat(last.stopNum) || 0) + 1);
    const phase = last.phase || '1';
    const tour = last.tour || 'Z1';
    const color = phaseColors[phase] || last.color || COLOR_PALETTE[0];
    return { ...initialStopState, stopNum: nextNum, phase, tour, color };
  };

  const importExcel = async (e) => {
    const file = e.target.files[0];
    if (!file || !window.AMap || (userRole !== 'admin' && userRole !== 'write')) { e.target.value = null; return; }
    try {
      const { stops: stopRows, returns: returnRows } = await parseExcelFile(file);
      if (!window.confirm(t.importEx + "?")) { e.target.value = null; return; }
      const geocoder = new window.AMap.Geocoder();
      pushHistory();
      setImportStatus({ active: true, current: 0, total: stopRows.length, cityName: '' });
      await dataService.clearStops(currentProject);
      await dataService.clearPhaseReturns(currentProject);

      const importedCoords = [];
      const localPhaseColors = {};
      for (const [index, row] of stopRows.entries()) {
        const tour = getRowValue(row, ['week', '周次', 'tour', 'region', '区域', '路线', '巡展', '活动', '项目']) || 'Z1';
        const stopNum = getRowValue(row, ['stop#', 'stop', '站号', '序号']) || String(index + 1);
        const phase = getRowValue(row, ['phase', '阶段']) || '1';
        const colorNum = parseInt(getRowValue(row, ['color', '颜色']) || '1', 10);
        const province = getRowValue(row, ['province', '省']);
        const city = getRowValue(row, ['city', '城市', '市', 'name']) || '';
        const venue = getRowValue(row, ['venue', '场馆', 'location']) || '';
        const contact = getRowValue(row, ['contact', '联系人', '姓名']);
        const phone = getRowValue(row, ['phone', '电话', '手机']);
        const company = getRowValue(row, ['company', '公司', '单位']);
        const position = getRowValue(row, ['position', 'title', '职务', '职位']);
        const notes = getRowValue(row, ['more info', '备注', '说明', '详情', 'notes']) || '';
        const startDate = getRowValue(row, ['start date', '开始日期', 'date', '日期', 'start']);
        const endDate = getRowValue(row, ['end date', '结束日期', 'end']) || startDate;

        const statusVal = getRowValue(row, ['status', '状态', '确认']) || '';
        const strStatus = String(statusVal).trim().toLowerCase();
        const isCompleted = strStatus.includes('完成') || strStatus.includes('completed') || strStatus === 'done';
        const isConfirmed = (strStatus.includes('确认') && !strStatus.includes('待确认')) || strStatus.includes('confirmed') || strStatus === 'ok' || strStatus === 'yes' || strStatus === 'true';
        const parsedStatus = isCompleted ? 'Completed' : (isConfirmed ? 'Confirmed' : 'TBC');
        let assignedColor = '#3b82f6';
        if (localPhaseColors[phase]) {
            assignedColor = localPhaseColors[phase];
        } else {
            const paletteIndex = (colorNum - 1) % COLOR_PALETTE.length;
            assignedColor = COLOR_PALETTE[paletteIndex] || '#3b82f6';
            localPhaseColors[phase] = assignedColor;
        }
        const searchStr = `${province || ''} ${city} ${venue}`.trim();
        if (!searchStr) continue;
        setImportStatus(prev => ({ ...prev, current: index + 1, cityName: city || province }));
        await new Promise(resolve => {
          const finish = () => setTimeout(resolve, 300);
          const saveStop = async (fLat, fLng, fProv, fCity) => {
            if (!venue) {
              const overlaps = importedCoords.filter(c => Math.abs(c.lat - fLat) < 0.02 && Math.abs(c.lng - fLng) < 0.02);
              if (overlaps.length > 0) {
                const angle = overlaps.length * (Math.PI / 3); const radius = 0.05 + Math.floor(overlaps.length / 6) * 0.05;
                fLng += radius * Math.cos(angle); fLat += radius * Math.sin(angle);
              }
            }
            importedCoords.push({ lat: fLat, lng: fLng });
            await dataService.addStop(currentProject, {
              tour, stopNum, province: fProv, name: fCity, venue, contact, phone, company, position, notes, phase, startDate: cleanDate(startDate), endDate: cleanDate(endDate), color: assignedColor, lat: fLat, lng: fLng, order: index, status: parsedStatus
            });
          };
          const geocodeFallback = () => {
            geocoder.getLocation(searchStr, async (gStatus, gResult) => {
              if (gStatus === 'complete' && gResult.geocodes.length) {
                const loc = gResult.geocodes[0].location;
                const ac = gResult.geocodes[0].addressComponent;
                await saveStop(loc.lat, loc.lng, province || ac.province || '', city || ac.city || ac.province || '');
              }
              finish();
            }, city || undefined);
          };
          if (venue && window.AMap && window.AMap.PlaceSearch) {
            const placeSearch = new window.AMap.PlaceSearch({ city: city || province || '全国', pageSize: 5, pageIndex: 1 });
            placeSearch.search(venue, async (pStatus, pResult) => {
              if (pStatus === 'complete' && pResult.poiList && pResult.poiList.pois && pResult.poiList.pois.length > 0) {
                const poi = pResult.poiList.pois[0];
                const poiProv = (poi.pname || '').replace(/省|市|自治区|壮族|回族|维吾尔/g, '');
                const expectProv = (province || '').replace(/省|市|自治区|壮族|回族|维吾尔/g, '');
                if (expectProv && poiProv && !poiProv.includes(expectProv) && !expectProv.includes(poiProv)) {
                  geocodeFallback(); return;
                }
                await saveStop(poi.location.lat, poi.location.lng, province || poi.pname || '', city || poi.cityname || poi.pname || '');
                finish();
              } else {
                geocodeFallback();
              }
            });
          } else {
            geocodeFallback();
          }
        });
      }

      // 导入返程点
      if (returnRows && returnRows.length > 0) {
        for (const [rIdx, retRow] of returnRows.entries()) {
          const retPhase = getRowValue(retRow, ['phase', '阶段']) || '';
          const retName = getRowValue(retRow, ['name', '名称']) || '';
          const retVenue = getRowValue(retRow, ['venue', '场馆']) || '';
          const retLat = parseFloat(getRowValue(retRow, ['lat', 'latitude', '纬度']));
          const retLng = parseFloat(getRowValue(retRow, ['lng', 'lon', 'longitude', '经度']));
          if (!retPhase) continue;
          setImportStatus(prev => ({ ...prev, current: stopRows.length + rIdx + 1, total: stopRows.length + returnRows.length, cityName: retName || retVenue }));

          if (!isNaN(retLat) && !isNaN(retLng) && retLat !== 0 && retLng !== 0) {
            // 有经纬度，直接保存
            await dataService.setPhaseReturn(currentProject, retPhase, { name: retName, venue: retVenue, lat: retLat, lng: retLng });
          } else if (retName || retVenue) {
            // 无经纬度，先地理编码
            const retSearch = `${retName} ${retVenue}`.trim();
            await new Promise(resolve => {
              geocoder.getLocation(retSearch, async (gStatus, gResult) => {
                if (gStatus === 'complete' && gResult.geocodes && gResult.geocodes.length) {
                  const loc = gResult.geocodes[0].location;
                  await dataService.setPhaseReturn(currentProject, retPhase, { name: retName, venue: retVenue, lat: loc.lat, lng: loc.lng });
                }
                resolve();
              });
            });
          }
          await new Promise(r => setTimeout(r, 200));
        }
      }

      setImportStatus({ active: false, current: 0, total: 0, cityName: '' });
    } catch (err) {
      console.error('Excel import error:', err);
      alert(lang === 'zh' ? 'Excel 解析失败，请检查文件格式' : 'Excel parsing failed, please check the file format');
    }
    e.target.value = null;
  };

