import * as XLSX from 'xlsx';
import { COLOR_PALETTE } from '../constants';
import { exportDateFormat } from '../utils';

// 根据颜色 hex 获取调色板编号（1-based）
const getPaletteNum = (hex) => {
  const idx = COLOR_PALETTE.indexOf(hex);
  return idx !== -1 ? idx + 1 : 1;
};

// 纯函数：根据站点数据生成 Excel 工作簿
// 参数：stops（站点数组）、calendarNotes（日期备注对象）、phaseReturns（阶段返程点对象）、lang（语言）、t（翻译对象）
// 返回：XLSX workbook 对象，由调用方触发下载
export const generateStopsWorkbook = (stops, calendarNotes, phaseReturns, lang, t) => {
  const isZh = lang === 'zh';

  const emptyRow = {
    [isZh ? '周次' : 'Week']: '',
    [isZh ? '站号' : 'Stop#']: '',
    [isZh ? '阶段' : 'Phase']: '',
    [isZh ? '颜色编号' : 'Color']: '',
    [isZh ? '省份' : 'Province']: '',
    [isZh ? '城市' : 'City']: '',
    [isZh ? '场馆' : 'Venue']: '',
    [isZh ? '联系人' : 'Contact']: '',
    [isZh ? '电话' : 'Phone']: '',
    [isZh ? '公司' : 'Company']: '',
    [isZh ? '职务' : 'Position']: '',
    [isZh ? '备注' : 'More Info']: '',
    [isZh ? '开始日期' : 'Start Date']: '',
    [isZh ? '结束日期' : 'End Date']: '',
    [isZh ? '状态' : 'Status']: '',
    [isZh ? '日历附注' : 'Calendar Note']: ''
  };

  const data = stops.length > 0 ? stops.map(s => ({
    [isZh ? '周次' : 'Week']: s.tour || 'Z1',
    [isZh ? '站号' : 'Stop#']: s.stopNum || '',
    [isZh ? '阶段' : 'Phase']: s.phase,
    [isZh ? '颜色编号' : 'Color']: getPaletteNum(s.color),
    [isZh ? '省份' : 'Province']: s.province || '',
    [isZh ? '城市' : 'City']: s.name,
    [isZh ? '场馆' : 'Venue']: s.venue,
    [isZh ? '联系人' : 'Contact']: s.contact || '',
    [isZh ? '电话' : 'Phone']: s.phone || '',
    [isZh ? '公司' : 'Company']: s.company || '',
    [isZh ? '职务' : 'Position']: s.position || '',
    [isZh ? '备注' : 'More Info']: s.notes || '',
    [isZh ? '开始日期' : 'Start Date']: exportDateFormat(s.startDate, lang),
    [isZh ? '结束日期' : 'End Date']: exportDateFormat(s.endDate || s.startDate, lang),
    [isZh ? '状态' : 'Status']: s.status === 'Completed' ? t.completed : (s.status === 'Confirmed' ? t.confirmed : t.tbc),
    [isZh ? '日历附注' : 'Calendar Note']: calendarNotes[s.startDate] || ''
  })) : [emptyRow];

  const ws = XLSX.utils.json_to_sheet(data);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, isZh ? '站点' : 'Stops');

  // 返程点 Sheet
  const returnEntries = phaseReturns ? Object.entries(phaseReturns) : [];
  const returnEmptyRow = {
    [isZh ? '阶段' : 'Phase']: '',
    [isZh ? '名称' : 'Name']: '',
    [isZh ? '场馆' : 'Venue']: '',
    [isZh ? '纬度' : 'Lat']: '',
    [isZh ? '经度' : 'Lng']: ''
  };
  const returnData = returnEntries.length > 0 ? returnEntries.map(([phase, ret]) => ({
    [isZh ? '阶段' : 'Phase']: phase,
    [isZh ? '名称' : 'Name']: ret.name || '',
    [isZh ? '场馆' : 'Venue']: ret.venue || '',
    [isZh ? '纬度' : 'Lat']: ret.lat,
    [isZh ? '经度' : 'Lng']: ret.lng
  })) : [returnEmptyRow];
  const wsReturns = XLSX.utils.json_to_sheet(returnData);
  XLSX.utils.book_append_sheet(wb, wsReturns, isZh ? '返程点' : 'Returns');

  return wb;
};

// 纯函数：解析 Excel 文件为站点行数组和返程点行数组
// 参数：file（File 对象）
// 返回：Promise<{stops: Array, returns: Array}>，解析出的原始行数据
export const parseExcelFile = (file) => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const wb = XLSX.read(new Uint8Array(evt.target.result), { type: 'array', cellDates: true });
        // 读取站点 Sheet（第一个 Sheet，或名为 "站点"/"Stops" 的 Sheet）
        const stopsSheetName = wb.SheetNames.find(n => n === '站点' || n === 'Stops') || wb.SheetNames[0];
        const stops = XLSX.utils.sheet_to_json(wb.Sheets[stopsSheetName], { raw: false, dateNF: 'yyyy-mm-dd' });
        // 读取返程点 Sheet（名为 "返程点"/"Returns" 的 Sheet，不存在则返回空数组）
        const returnsSheetName = wb.SheetNames.find(n => n === '返程点' || n === 'Returns');
        const returns = returnsSheetName ? XLSX.utils.sheet_to_json(wb.Sheets[returnsSheetName], { raw: false }) : [];
        resolve({ stops, returns });
      } catch (e) {
        reject(e);
      }
    };
    reader.onerror = reject;
    reader.readAsArrayBuffer(file);
  });
};

// 从 Excel 行中提取字段值（支持多语言列名匹配）
// 参数：row（单行对象）、keywords（关键词数组）
// 返回：匹配到的字段值字符串，未匹配返回空字符串
export const getRowValue = (row, keywords) => {
  const key = Object.keys(row).find(k => keywords.some(kw => k.toLowerCase().includes(kw)));
  return key ? String(row[key]).trim() : '';
};
