import { useState, useEffect, useCallback } from 'react';
import { SESSION_EXPIRY_MS } from '../constants';
import * as dataService from '../services/dataService';

/**
 * 认证与权限管理 Hook
 * 封装：密码验证、角色判断、会话恢复、密码修改模态框、分享模态框
 * 为未来用户注册系统和多用户协作打基础
 */
export function useAuth(lang, t) {
  const [userRole, setUserRole] = useState(null);
  const [passLoaded, setPassLoaded] = useState(false);
  const [globalPassConfig, setGlobalPassConfig] = useState({ admin: '', view: '', write: '' });
  const [loginPass, setLoginPass] = useState('');
  const [passModal, setPassModal] = useState({ show: false, type: '', title: '' });
  const [modalInput, setModalInput] = useState('');
  const [shareModal, setShareModal] = useState({ show: false, link: '', pass: '' });

  // 监听 Firebase 密码配置，并从 localStorage 恢复会话
  useEffect(() => {
    const unsub = dataService.watchPasswords((config) => {
      config = config || {};
      setGlobalPassConfig(config);
      setPassLoaded(true);
      const savedSession = localStorage.getItem('rp2026_session');
      if (savedSession) {
        try {
          const parsedSession = JSON.parse(savedSession);
          if (Date.now() < parsedSession.expires) setUserRole(parsedSession.role);
          else localStorage.removeItem('rp2026_session');
        } catch (e) { localStorage.removeItem('rp2026_session'); }
      }
    });
    return () => unsub();
  }, []);

  // 登录：验证密码并设置角色
  const login = useCallback(() => {
    if (!passLoaded) return;
    const p = loginPass.trim();
    if (!p) { alert(t.wrongPass); return; }
    let matchedRole = null;
    const adminPass = globalPassConfig.admin || 'admin';
    if (p === adminPass) matchedRole = 'admin';
    else if (globalPassConfig.write && p === globalPassConfig.write) matchedRole = 'write';
    else if (globalPassConfig.view && p === globalPassConfig.view) matchedRole = 'view';
    if (matchedRole) {
      setUserRole(matchedRole);
      localStorage.setItem('rp2026_session', JSON.stringify({ role: matchedRole, expires: Date.now() + SESSION_EXPIRY_MS }));
    } else { alert(t.wrongPass); }
    setLoginPass('');
  }, [passLoaded, loginPass, globalPassConfig, t]);

  // 登出（刷新页面）
  const logout = useCallback(() => {
    localStorage.removeItem('rp2026_session');
    window.location.reload();
  }, []);

  // 软登出（不刷新，仅清除会话和角色）
  const softLogout = useCallback(() => {
    localStorage.removeItem('rp2026_session');
    setUserRole(null);
  }, []);

  // 提交密码修改
  const submitPassModal = useCallback(async () => {
    if (modalInput.trim() === '') { alert(lang === 'zh' ? '密码不能为空' : 'Password cannot be blank'); return; }
    await dataService.updatePasswords({ [passModal.type]: modalInput.trim() });
    setPassModal({ show: false, type: '', title: '' });
  }, [modalInput, passModal, lang]);

  // 打开密码修改模态框
  const openPassModal = useCallback((type, title) => {
    setModalInput('');
    setPassModal({ show: true, type, title });
  }, []);

  // 关闭密码修改模态框
  const closePassModal = useCallback(() => {
    setPassModal({ show: false, type: '', title: '' });
  }, []);

  // 打开分享模态框
  const openShareModal = useCallback((link, pass) => {
    setShareModal({ show: true, link, pass });
  }, []);

  // 关闭分享模态框
  const closeShareModal = useCallback(() => {
    setShareModal({ show: false, link: '', pass: '' });
  }, []);

  return {
    userRole, setUserRole,
    passLoaded, globalPassConfig,
    loginPass, setLoginPass,
    passModal, setPassModal, modalInput, setModalInput,
    shareModal, setShareModal,
    login, logout, softLogout, submitPassModal,
    openPassModal, closePassModal, openShareModal, closeShareModal,
  };
}
